const property = items[0].json;
const formatted = {
  title: property.title,
  description: property.description,
  price: property.price,
  location: property.location,
  specs: property.specs,
  images: property.images,
  features: property.features,
  listingType: property.listingType,
  agent: property.agent,
};

items.json = [{ formatted }];
return items;

const formatted = items.json[0];
const apiKey = $const('TWITTER_API_KEY');
const apiSecret = $const('TWITTER_API_SECRET');

if (!apiKey || !apiSecret) {
  throw new Error('Twitter API Key or Secret not configured');
}

const tweetText = `${formatted.title}\n💰 R${formatted.price.toLocaleString()} - ${formatted.listingType === 'sale' ? 'For Sale' : 'For Rent'}\n📍 ${formatted.location.suburb}, ${formatted.location.city}\n${formatted.specs.bedrooms}BR ${formatted.specs.bathrooms}BA\n${formatted.hashtags.slice(0, 3).join(' ')}`;

const response = await fetch('https://api.twitter.com/2/tweets', {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${apiKey}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({ text: tweetText }),
});

if (!response.ok) {
  throw new Error(`Failed to post to Twitter: ${response.status}`);
}

const data = await response.json();
items.json = [{ postUrl: `https://twitter.com/i/status/${data.data.id}` }];
return items;

const result = {
  platform: 'twitter',
  success: true,
  postUrl: items.json[0].postUrl,
};
items.json = [result];
return items;

const result = items.json[0];
const webhookUrl = $const('WEBHOOK_URL');

if (webhookUrl) {
  await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ result, platform: 'twitter' }),
  });
}

return items;
